package com.sherifradwan.ancnative.model

import java.time.LocalDate
import java.time.temporal.ChronoUnit

fun daysToEdd(edd: LocalDate, asOf: LocalDate): Long = ChronoUnit.DAYS.between(asOf, edd)

data class GestationalAgeResult(
    val weeks: Int,
    val days: Int,
    val totalDays: Long,
    val formatted: String,
    val trimester: Int,
    val isPostTerm: Boolean = false,
) {
    val displayText: String get() = formatted
    val isPostConception: Boolean get() = totalDays >= 0
    val isLateTerm: Boolean get() = weeks == 41
    val progressFraction: Float get() = (totalDays / FULL_TERM_DAYS.toFloat()).coerceIn(0f, 1f)
    val shortWeeksText: String get() = "${weeks}+${days} wks"
}

data class DueDatesByMethod(
    val lmp: LocalDate?,
    val ivf: LocalDate?,
    val scan: LocalDate?,
)

object GestationalAgeEngine {

    fun dueDateForMethod(dating: DemoPatientDating, method: String?): LocalDate? {
        return when (method?.uppercase()) {
            "IVF_TRANSFER", "IVF" -> {
                if (!dating.transferDate.isNullOrBlank()) {
                    val transfer = parseIsoDateOrNull(dating.transferDate) ?: return null
                    val embryoAge = dating.embryoAgeDays ?: 5
                    if (embryoAge !in ClinicalVocabulary.embryoAges) return null
                    ivfEddFromTransfer(transfer, embryoAge)
                } else null
            }
            "ULTRASOUND", "US" -> {
                if (!dating.ultrasoundEdd.isNullOrBlank()) {
                    parseIsoDateOrNull(dating.ultrasoundEdd)
                } else null
            }
            "LMP" -> {
                if (!dating.lmpDate.isNullOrBlank()) {
                    val lmp = parseIsoDateOrNull(dating.lmpDate) ?: return null
                    eddFromLmp(lmp)
                } else null
            }
            else -> {
                val scan = if (!dating.ultrasoundEdd.isNullOrBlank()) {
                    parseIsoDateOrNull(dating.ultrasoundEdd)
                } else null
                scan ?: dueDateForMethod(dating, "LMP")
            }
        }
    }

    fun dueDatesByMethod(dating: DemoPatientDating): DueDatesByMethod {
        return DueDatesByMethod(
            lmp = dueDateForMethod(dating, "LMP"),
            ivf = dueDateForMethod(dating, "IVF_TRANSFER"),
            scan = dueDateForMethod(dating, "Ultrasound"),
        )
    }

    fun calculateGestationalAgeAt(dating: DemoPatientDating?, dateString: String?): GestationalAgeResult? {
        if (dateString.isNullOrBlank()) return null
        val date = parseIsoDateOrNull(dateString) ?: return null
        return calculate(dating, date)
    }

    fun calculate(dating: DemoPatientDating?, asOfDate: LocalDate = LocalDate.now()): GestationalAgeResult? {
        val edd = calculateEstimatedDueDate(dating) ?: return null
        return calculateForEdd(edd, asOfDate)
    }

    fun calculateForLmp(lmpDate: LocalDate, asOfDate: LocalDate = LocalDate.now()): GestationalAgeResult? {
        val totalDays = ChronoUnit.DAYS.between(lmpDate, asOfDate)
        if (totalDays < 0 || totalDays > 320) return null
        return formatGestationalDays(totalDays)
    }

    fun calculateForIvf(transferDate: LocalDate, embryoAgeDays: Int, asOfDate: LocalDate = LocalDate.now()): GestationalAgeResult? {
        if (embryoAgeDays !in ClinicalVocabulary.embryoAges) return null
        val daysSinceTransfer = ChronoUnit.DAYS.between(transferDate, asOfDate)
        val totalDays = ivfGaDaysAtTransfer(embryoAgeDays) + daysSinceTransfer
        if (totalDays < 0 || totalDays > 320) return null
        return formatGestationalDays(totalDays)
    }

    fun calculateForEdd(edd: LocalDate, asOfDate: LocalDate = LocalDate.now()): GestationalAgeResult? {
        val daysToEdd = daysToEdd(edd, asOfDate)
        val totalDays = FULL_TERM_DAYS - daysToEdd
        if (totalDays < 0 || totalDays > 320) return null
        return formatGestationalDays(totalDays)
    }

    fun calculateEstimatedDueDate(dating: DemoPatientDating?): LocalDate? {
        if (dating == null) return null
        if (!dating.agreedEdd.isNullOrBlank()) {
            parseIsoDateOrNull(dating.agreedEdd)?.let { return it }
        }
        return dueDateForMethod(dating, dating.datingMethod)
    }

    private fun formatGestationalDays(totalDays: Long): GestationalAgeResult {
        val weeks = (totalDays / 7).toInt()
        val days = (totalDays % 7).toInt()
        val isPostTerm = weeks >= 42
        val formatted = if (isPostTerm) {
            "${weeks}w ${days}d (Post-term)"
        } else {
            "${weeks}w ${days}d"
        }
        val trimester = when {
            weeks < 14 -> 1
            weeks < 28 -> 2
            else -> 3
        }
        return GestationalAgeResult(
            weeks = weeks,
            days = days,
            totalDays = totalDays,
            formatted = formatted,
            trimester = trimester,
            isPostTerm = isPostTerm,
        )
    }
}

package com.sherifradwan.ancnative.state

import com.sherifradwan.ancnative.model.DemoPatientDating
import com.sherifradwan.ancnative.model.GestationalAgeEngine
import com.sherifradwan.ancnative.model.parseIsoDateOrNull

internal fun datingDraftToDating(patientId: String, values: DatingDraftValues): DemoPatientDating {
    return DemoPatientDating(
        patientId = patientId,
        lmpDate = values.lmpDate.ifBlank { null },
        ultrasoundEdd = values.ultrasoundEdd.ifBlank { null },
        agreedEdd = values.agreedEdd.ifBlank { null },
        datingMethod = values.datingMethod.ifBlank { null },
        transferDate = values.transferDate.ifBlank { null },
        embryoAgeDays = values.embryoAgeDays.toIntOrNull(),
        notes = values.notes.ifBlank { null },
    )
}

internal fun isManualAgreedEdd(values: DatingDraftValues): Boolean {
    val agreed = values.agreedEdd.trim()
    if (agreed.isEmpty()) return false
    val dating = datingDraftToDating("", values.copy(agreedEdd = ""))
    val methodEdd = GestationalAgeEngine.dueDateForMethod(dating, dating.datingMethod)
    val parsedAgreed = parseIsoDateOrNull(agreed)
    return if (parsedAgreed != null) {
        parsedAgreed != methodEdd
    } else {
        true
    }
}

internal fun applyDatingChange(
    values: DatingDraftValues,
    field: DatingDraftField,
    value: String,
): DatingDraftValues {
    val wasManual = isManualAgreedEdd(values)
    val updated = when (field) {
        DatingDraftField.LMP_DATE -> values.copy(lmpDate = value)
        DatingDraftField.ULTRASOUND_EDD -> values.copy(ultrasoundEdd = value)
        DatingDraftField.DATING_METHOD -> values.copy(datingMethod = value)
        DatingDraftField.TRANSFER_DATE -> values.copy(transferDate = value)
        DatingDraftField.EMBRYO_AGE_DAYS -> values.copy(embryoAgeDays = value)
        DatingDraftField.AGREED_EDD -> values.copy(agreedEdd = value)
        DatingDraftField.NOTES -> values.copy(notes = value)
    }
    return when (field) {
        DatingDraftField.LMP_DATE,
        DatingDraftField.ULTRASOUND_EDD,
        DatingDraftField.DATING_METHOD,
        DatingDraftField.TRANSFER_DATE,
        DatingDraftField.EMBRYO_AGE_DAYS -> {
            if (wasManual) {
                updated
            } else {
                val newDating = datingDraftToDating("", updated.copy(agreedEdd = ""))
                val newMethodEdd = GestationalAgeEngine.dueDateForMethod(newDating, newDating.datingMethod)
                updated.copy(agreedEdd = newMethodEdd?.toString() ?: "")
            }
        }
        DatingDraftField.AGREED_EDD,
        DatingDraftField.NOTES -> updated
    }
}

package com.sherifradwan.ancnative.state

import com.sherifradwan.ancnative.model.GestationalAgeEngine
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.LocalDate

class DatingDraftRuleTest {

    private val asOf = LocalDate.of(2026, 8, 1)

    private fun totalDays(values: DatingDraftValues): Long =
        GestationalAgeEngine.calculate(datingDraftToDating("p1", values), asOf)!!.totalDays

    private fun change(values: DatingDraftValues, field: DatingDraftField, value: String) =
        applyDatingChange(values, field, value)

    private val lmpDraft = DatingDraftValues(lmpDate = "2026-02-01", agreedEdd = "2026-11-08", datingMethod = "LMP")
    private val ivfDraft = DatingDraftValues(
        agreedEdd = "2026-11-19",
        datingMethod = "IVF_TRANSFER",
        transferDate = "2026-03-01",
        embryoAgeDays = "3",
    )

    @Test
    fun draftToDatingTurnsBlanksIntoNullAndParsesEmbryoDay() {
        val dating = datingDraftToDating("p9", DatingDraftValues(embryoAgeDays = "5", lmpDate = "2026-02-01"))
        assertEquals("p9", dating.patientId)
        assertEquals("2026-02-01", dating.lmpDate)
        assertNull(dating.ultrasoundEdd)
        assertNull(dating.agreedEdd)
        assertNull(dating.datingMethod)
        assertNull(dating.transferDate)
        assertNull(dating.notes)
        assertEquals(5, dating.embryoAgeDays)
        assertNull(datingDraftToDating("p9", DatingDraftValues(embryoAgeDays = "x")).embryoAgeDays)
    }

    @Test
    fun lmpEditWithBlankAgreedSetsAgreedAndMovesGestationalAge() {
        val before = DatingDraftValues(lmpDate = "2026-02-01", datingMethod = "LMP")
        val after = change(before, DatingDraftField.LMP_DATE, "2026-02-08")
        assertEquals("2026-11-15", after.agreedEdd)
        assertEquals(7L, totalDays(before) - totalDays(after))
    }

    @Test
    fun lmpEditFollowsWhenAgreedEqualsOldMethodDate() {
        val after = change(lmpDraft, DatingDraftField.LMP_DATE, "2026-02-08")
        assertEquals("2026-11-15", after.agreedEdd)
        assertEquals(7L, totalDays(lmpDraft) - totalDays(after))
    }

    @Test
    fun embryoDayEditsMoveAgreedAndGestationalAge() {
        val day5 = change(ivfDraft, DatingDraftField.EMBRYO_AGE_DAYS, "5")
        assertEquals("2026-11-17", day5.agreedEdd)
        assertEquals(2L, totalDays(day5) - totalDays(ivfDraft))
        val day6 = change(day5, DatingDraftField.EMBRYO_AGE_DAYS, "6")
        assertEquals("2026-11-16", day6.agreedEdd)
        assertEquals(1L, totalDays(day6) - totalDays(day5))
    }

    @Test
    fun transferDateEditMovesFollowingAgreed() {
        val after = change(ivfDraft, DatingDraftField.TRANSFER_DATE, "2026-03-08")
        assertEquals("2026-11-26", after.agreedEdd)
    }

    @Test
    fun switchingMethodRepointsFollowingAgreed() {
        val draft = lmpDraft.copy(transferDate = "2026-03-01", embryoAgeDays = "5")
        val after = change(draft, DatingDraftField.DATING_METHOD, "IVF_TRANSFER")
        assertEquals("2026-11-17", after.agreedEdd)
    }

    @Test
    fun scanEditFollowsWhenMethodIsUltrasound() {
        val draft = DatingDraftValues(ultrasoundEdd = "2026-11-10", agreedEdd = "2026-11-10", datingMethod = "Ultrasound")
        assertEquals("2026-11-12", change(draft, DatingDraftField.ULTRASOUND_EDD, "2026-11-12").agreedEdd)
    }

    @Test
    fun manualAgreedDateIsUntouchedByInputEdits() {
        val manual = lmpDraft.copy(agreedEdd = "2026-12-01")
        assertTrue(isManualAgreedEdd(manual))
        assertEquals("2026-12-01", change(manual, DatingDraftField.LMP_DATE, "2026-02-08").agreedEdd)
        val manualIvf = ivfDraft.copy(agreedEdd = "2026-12-01")
        assertTrue(isManualAgreedEdd(manualIvf))
        assertEquals("2026-12-01", change(manualIvf, DatingDraftField.EMBRYO_AGE_DAYS, "6").agreedEdd)
    }

    @Test
    fun followingAgreedIsNotManual() {
        assertFalse(isManualAgreedEdd(lmpDraft))
        assertFalse(isManualAgreedEdd(DatingDraftValues(lmpDate = "2026-02-01", datingMethod = "LMP")))
    }

    @Test
    fun clearingAgreedMakesTheNextLmpEditFollow() {
        val cleared = change(lmpDraft.copy(agreedEdd = "2026-12-01"), DatingDraftField.AGREED_EDD, "")
        assertEquals("", cleared.agreedEdd)
        assertEquals("2026-11-15", change(cleared, DatingDraftField.LMP_DATE, "2026-02-08").agreedEdd)
    }

    @Test
    fun typingAgreedDateMakesItManualAndOnlySetsTheField() {
        val typed = change(lmpDraft, DatingDraftField.AGREED_EDD, "2026-12-01")
        assertEquals(lmpDraft.copy(agreedEdd = "2026-12-01"), typed)
        assertTrue(isManualAgreedEdd(typed))
    }

    @Test
    fun halfTypedDateGivesBlankAgreedWithoutCrash() {
        val after = change(lmpDraft, DatingDraftField.LMP_DATE, "2026-02-")
        assertEquals("2026-02-", after.lmpDate)
        assertEquals("", after.agreedEdd)
    }

    @Test
    fun notesEditNeverChangesAgreed() {
        val after = change(lmpDraft, DatingDraftField.NOTES, "scan later")
        assertEquals("scan later", after.notes)
        assertEquals(lmpDraft.agreedEdd, after.agreedEdd)
    }
}

private fun updatePregnancyDraft(state: AncState, event: AncEvent.PregnancyDraftChanged): AncState {
    if (state.savePhase.blocksEditing()) return state
    val draft = state.pregnancyDraft ?: return state
    val values = when (event.field) {
        PregnancyDraftField.DATE_TEXT -> draft.values.copy(dateText = event.value)
        PregnancyDraftField.OUTCOME_TEXT -> draft.values.copy(outcomeText = event.value)
        PregnancyDraftField.PREGNANCY_TYPE -> draft.values.copy(pregnancyType = event.value)
        PregnancyDraftField.OTHER_DETAILS -> draft.values.copy(otherDetails = event.value)
        PregnancyDraftField.PLACE_AND_DOCTOR -> draft.values.copy(placeAndDoctor = event.value)
        PregnancyDraftField.DELIVERY_BY -> draft.values.copy(deliveryBy = event.value)
        PregnancyDraftField.OUTCOME -> draft.values.copy(
            outcome = event.value,
            birthMethod = draft.values.birthMethod.takeIf {
                event.value == "LiveBirth" || event.value == "Stillbirth"
            }.orEmpty(),
            lossManagement = draft.values.lossManagement.takeIf {
                event.value == "EarlyPregnancyLoss"
            }.orEmpty(),
            terminationMethod = draft.values.terminationMethod.takeIf {
                event.value == "TerminationOfPregnancy"
            }.orEmpty(),
        )
        PregnancyDraftField.BIRTH_METHOD -> draft.values.copy(birthMethod = event.value)
        PregnancyDraftField.LOSS_MANAGEMENT -> draft.values.copy(lossManagement = event.value)
        PregnancyDraftField.TERMINATION_METHOD -> draft.values.copy(terminationMethod = event.value)
        PregnancyDraftField.CLINICIAN_ID -> draft.values.copy(clinicianId = event.value)
    }
    return state.copy(pregnancyDraft = draft.copy(values = values, errors = emptySet()), savePhase = SavePhase.IDLE, saveError = null)
}

private fun updateDatingDraft(state: AncState, event: AncEvent.DatingDraftChanged): AncState {
    if (state.savePhase.blocksEditing()) return state
    val draft = state.datingDraft ?: return state
    val values = applyDatingChange(draft.values, event.field, event.value)
    return state.copy(datingDraft = draft.copy(values = values, errors = emptySet()), savePhase = SavePhase.IDLE, saveError = null)
}

private fun updateUltrasoundDraft(state: AncState, event: AncEvent.UltrasoundDraftChanged): AncState {
    if (state.savePhase.blocksEditing()) return state
    val draft = state.ultrasoundDraft ?: return state
    val values = when (event.field) {
        UltrasoundDraftField.DATE -> draft.values.copy(date = event.value)
        UltrasoundDraftField.GA_WEEKS -> draft.values.copy(gaWeeks = event.value)
        UltrasoundDraftField.GA_DAYS -> draft.values.copy(gaDays = event.value)
        UltrasoundDraftField.FETAL_NUMBER -> draft.values.copy(fetalNumber = event.value)
        UltrasoundDraftField.PRESENTATION -> draft.values.copy(presentation = event.value)
        UltrasoundDraftField.PLACENTAL_SITE -> draft.values.copy(placentalSite = event.value)
        UltrasoundDraftField.AMNIOTIC_FLUID -> draft.values.copy(amnioticFluid = event.value)
        UltrasoundDraftField.FETAL_HEART_RATE -> draft.values.copy(fetalHeartRate = event.value)
        UltrasoundDraftField.BIOMETRY_BPD -> draft.values.copy(biometryBpd = event.value)
        UltrasoundDraftField.BIOMETRY_HC -> draft.values.copy(biometryHc = event.value)
        UltrasoundDraftField.BIOMETRY_AC -> draft.values.copy(biometryAc = event.value)
        UltrasoundDraftField.BIOMETRY_FL -> draft.values.copy(biometryFl = event.value)
        UltrasoundDraftField.ESTIMATED_FETAL_WEIGHT -> draft.values.copy(estimatedFetalWeight = event.value)
        UltrasoundDraftField.IMPRESSION -> draft.values.copy(impression = event.value)
        UltrasoundDraftField.LINKED_VISIT -> draft.values.copy(linkedVisitId = event.value)
        UltrasoundDraftField.IMAGE_URIS -> draft.values.copy(
            imageUris = if (event.value.isBlank()) emptyList() else event.value.split(",").map { it.trim() }.filter { it.isNotEmpty() },
        )
    }
    return state.copy(ultrasoundDraft = draft.copy(values = values, errors = emptySet()), savePhase = SavePhase.IDLE, saveError = null)
}

